    if (!query) return commandEntries().slice(0, 5)

    return commandEntries().filter((entry) => matchesCommandPaletteEntry(entry, query))
  }

  onCleanup(() => {
    if (state.committed) return
    state.cleanup?.()
  })

  return (
    <CommandPaletteView
      placeholder={language.t("palette.search.placeholder.home")}
      items={items}
      sources={[sessions]}
      highlight={highlight}
      select={select}
      close={() => dialog.close()}
    />
  )
}

